'use client';

import { revalidateTag } from 'next/cache';
import { useState } from 'react';
import ProductsList, { invalidateProductsCache } from './ProductsList';

export default function Page() {
  const [isInvalidating, setIsInvalidating] = useState(false);

  const handleInvalidateCache = async () => {
    setIsInvalidating(true);
    try {
      await invalidateProductsCache();
      // In a real app, you might want to refetch data here
      console.log('Products cache invalidated successfully');
    } catch (error) {
      console.error('Failed to invalidate cache:', error);
    } finally {
      setIsInvalidating(false);
    }
  };

  return (
    <div className="container mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold">Product Listing</h1>
        <form action={invalidateProductsCache}>
          <button
            type="submit"
            disabled={isInvalidating}
            className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded disabled:opacity-50"
          >
            {isInvalidating ? 'Invalidating...' : 'Invalidate Cache'}
          </button>
        </form>
      </div>

      <ProductsList />

      <div className="mt-8 p-4 bg-gray-100 rounded-lg">
        <h3 className="font-semibold mb-2">Cache Implementation Details:</h3>
        <ul className="list-disc list-inside space-y-1 text-sm text-gray-700">
          <li>Products data is cached using the &quot;use cache&quot; directive</li>
          <li>Cache is tagged with &quot;products&quot; for selective invalidation</li>
          <li>Server action invalidates the cache when form is submitted</li>
          <li>Next.js will refetch data on next request after invalidation</li>
        </ul>
      </div>
    </div>
  );
}

